// db_gl_dist.h - the posted General Ledger lines (spec #2 5.4).
//
// Generated by dbf2sqlite --headers-out from the real GL_DIST.DBF, then
// hand-checked:
//   - class renamed Tgl_dist -> Tgldist, the name gl_postb.cpp / gl_postr.cpp use;
//   - default tag "batchno" (string 8140, which gl_postr.cpp selects). The
//     generator picked the first tag, "ardist", whose FOR TYPE = 'AR' would
//     hide every GL line from top()/skip()/seek().
// Tags in the real table: ardist, apdist (FOR TYPE = 'AR' / 'AP'), descript,
// batchno, account (ACCOUNT+DEPT).
//
// include/db_dist.h also declares a Tgldist, but it is the older AR snapshot's
// class and opens ar_jsum. Never include both in one file.
#ifndef DB_GL_DIST_H
#define DB_GL_DIST_H

class Tgldist : public Data4
{
public:
    Field4* account = nullptr;     // ACCOUNT C(7)
    Field4* dept = nullptr;        // DEPT C(4)
    Field4* medrep = nullptr;      // MEDREP C(5)
    Field4* drcode = nullptr;      // DRCODE C(5)
    Field4* prod = nullptr;        // PROD C(7)
    Field4* period = nullptr;      // PERIOD C(4)
    Field4* date = nullptr;        // DATE C(10)
    Field4* type = nullptr;        // TYPE C(3)
    Field4* batchno = nullptr;     // BATCHNO N(6)
    Field4* reference = nullptr;   // REFERENCE C(30)
    Field4* cheque = nullptr;      // CHEQUE C(7)
    Field4* descript = nullptr;    // DESCRIPT C(50)
    Field4* debit = nullptr;       // DEBIT N(16,2)
    Field4* credit = nullptr;      // CREDIT N(16,2)

    Tgldist(Code4* code, LPSTR = 0) : Data4(code, "gl_dist")
    {
        if (!isValid())
            return;
        SetIndex("batchno");
        top();
        account = new Field4(*this, "ACCOUNT");
        dept = new Field4(*this, "DEPT");
        medrep = new Field4(*this, "MEDREP");
        drcode = new Field4(*this, "DRCODE");
        prod = new Field4(*this, "PROD");
        period = new Field4(*this, "PERIOD");
        date = new Field4(*this, "DATE");
        type = new Field4(*this, "TYPE");
        batchno = new Field4(*this, "BATCHNO");
        reference = new Field4(*this, "REFERENCE");
        cheque = new Field4(*this, "CHEQUE");
        descript = new Field4(*this, "DESCRIPT");
        debit = new Field4(*this, "DEBIT");
        credit = new Field4(*this, "CREDIT");
    }

    ~Tgldist()
    {
        delete account;
        delete dept;
        delete medrep;
        delete drcode;
        delete prod;
        delete period;
        delete date;
        delete type;
        delete batchno;
        delete reference;
        delete cheque;
        delete descript;
        delete debit;
        delete credit;
    }

    Tgldist(const Tgldist&) = delete;
    Tgldist& operator=(const Tgldist&) = delete;
};

#endif
